function render(){const d=docs[current];document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.id===current));document.getElementById('meta').innerHTML=`<span class="pill">${d.label}</span><span class="pill">${d.limit}</span><span class="pill">전략/작성 함수 공통</span>`;document.getElementById('count').textContent=current==='explanation'?'함수 흐름 설명':`${d.rows.length}개 작성 항목`;document.getElementById('rows').innerHTML=d.rows.map((r,i)=>{const f=functions[r[2]],key=current+'|'+r[0],value=state[key]||'';if(r[3]==='flow')return `<tr><td colspan="5"><div style="padding:0"><h2>전략·작성·검증 Agent 함수 흐름</h2><p>박상희 담당인 계획서 생성·검증 1과 정재희 검증 2를 연결한 흐름입니다.</p><div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;font-weight:700"><span class="pill">입력·FormSpec·Web·팀 데이터</span><b>→</b><span class="pill">전략 Agent<br>F02~F15</span><b>→</b><span class="pill">작성 Agent<br>F16~F18</span><b>→</b><span class="pill">검증 1<br>F19·rubric</span><b>→</b><span class="pill">검증 2·조립<br>F20</span></div><p class="hint" style="margin-top:18px">검증 실패 시 해당 섹션만 재생성합니다. featureList, sourceRef, evidenceLocator, 일정·예산 상한을 공통 계약으로 유지하고, 최종 결과는 sectionId·functionName·generatedText·validation 구조로 백엔드에 전달합니다.</p><h3>함수별 데이터 계약</h3><div style="overflow:auto"><table class="table"><thead><tr><th>단계</th><th>함수</th><th>주요 입력 속성</th><th>출력</th><th>연결 파일·속성</th></tr></thead><tbody><tr><td>F01</td><td class="fn">collect_web_data</td><td>query, source_type, target_fields</td><td>web_data</td><td>web_design_trends: trendName, description, keywords, evidence[]</td></tr><tr><td>F02</td><td class="fn">analyze_item</td><td>item_input, research_data</td><td>item_spec</td><td>development_knowledge: categories, items[] → coreFeatures</td></tr><tr><td>F03</td><td class="fn">analyze_market</td><td>item, market_data, analysis_type</td><td>market_analysis</td><td>raw_kiet_results: categories[], results[], summary</td></tr><tr><td>F04</td><td class="fn">analyze_competitors</td><td>item, market_data, competitor_data</td><td>competitor_analysis</td><td>KIET 근거 + Web evidence의 sourceUrl, supportingText</td></tr><tr><td>F05</td><td class="fn">analyze_team_capability</td><td>team_data, item_requirements</td><td>team_capability</td><td>대표·팀원 입력 + item_spec.coreFeatures</td></tr><tr><td>F06</td><td class="fn">define_development_goal</td><td>item_spec, duration, target_field</td><td>development_goal</td><td>coreFeatures → 목표·KPI·측정환경</td></tr><tr><td>F07</td><td class="fn">define_development_method</td><td>core_technologies, constraints</td><td>development_method</td><td>개발지식 items[] + 제약조건</td></tr><tr><td>F08</td><td class="fn">create_development_plan</td><td>goals, duration, phases</td><td>development_plan</td><td>goal·milestones → 단계별 추진내용</td></tr><tr><td>F09</td><td class="fn">create_production_plan</td><td>product, development_plan, phases</td><td>production_plan</td><td>개발계획 → 수요조사·기획·개발·테스트·양산</td></tr><tr><td>F10</td><td class="fn">create_marketing_strategy</td><td>item, market, target_customer, stage</td><td>marketing_strategy</td><td>market_analysis + trend evidence</td></tr><tr><td>F11</td><td class="fn">create_business_model</td><td>item, market, customer, strategy</td><td>business_model</td><td>고객·시장·마케팅 전략 → 수익모델</td></tr><tr><td>F12</td><td class="fn">create_growth_strategy</td><td>market, competitors, bm, investment, social_value</td><td>growth_strategy</td><td>F03·F04·F11 결과 통합</td></tr><tr><td>F13</td><td class="fn">create_resource_plan</td><td>item, required_capabilities, team, resource_type</td><td>resource_plan</td><td>F05 + coreFeatures → 장비·채용·협력기관</td></tr><tr><td>F14</td><td class="fn">calculate_budget</td><td>items, quantity, unit_price, phase, rules</td><td>budget</td><td>개발·자원·일정 + 지원금 상한 규칙</td></tr><tr><td>F15</td><td class="fn">create_schedule</td><td>tasks, duration, milestones</td><td>schedule</td><td>F08·F09·F14 → 기간·마일스톤 표</td></tr><tr><td>F16</td><td class="fn">generate_section</td><td>section_spec, source_data, writing_rules</td><td>section_content</td><td>keyword_list: programs/userKeywords + 모든 전략 결과</td></tr><tr><td>F17</td><td class="fn">generate_table</td><td>columns, rows, rules</td><td>table</td><td>F06 KPI, F14 예산, F15 일정</td></tr><tr><td>F18</td><td class="fn">generate_image_spec</td><td>item, architecture, flow_type</td><td>image_spec</td><td>F02 item_spec + development_knowledge</td></tr><tr><td>F19</td><td class="fn">validate_section</td><td>section_spec, content, source_data</td><td>validation_result</td><td>양식·rubric·sourceRef·수치·누락 검증</td></tr><tr><td>F20</td><td class="fn">assemble_document</td><td>sections, tables, images</td><td>document</td><td>generatedText + tables + images + validation</td></tr></tbody></table></div></div></td></tr>`;return `<tr><td class="section">${r[0]}</td><td>${r[1]}<div class="hint">입력: 분석·조사 결과 및 작성 규칙</div></td><td class="fn">${f[0]}<div class="hint">${r[2]} · ${r[3]}</div></td><td class="model">${f[1]}</td><td><textarea data-key="${key}" placeholder="GPT 생성 결과를 입력하거나 API 응답으로 채우세요.">${value}</textarea></td></tr>`}).join('');document.querySelectorAll('textarea').forEach(x=>x.oninput=()=>state[x.dataset.key]=x.value);if(current==='explanation'){document.querySelectorAll('#rows h3').forEach(h=>{if(h.textContent.includes('함수별 데이터 계약')){let n=h.previousElementSibling;while(n){const prev=n.previousElementSibling;n.remove();n=prev}}})}}
document.getElementById('tabs').innerHTML=Object.entries(docs).map(([id,d])=>`<button data-id="${id}">${d.label}</button>`).join('');document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>{current=b.dataset.id;render()});document.getElementById('export').onclick=()=>{const rows=docs[current].rows.map(r=>{const f=functions[r[2]],key=current+'|'+r[0];return {documentType:current,sectionId:r[0],functionName:f[0],model:f[1],contentType:r[3],generatedText:state[key]||'',tables:[],images:[],validation:{status:'pending',issues:[]}}});const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({documentType:current,results:rows},null,2)],{type:'application/json'}));a.download=`${current}_section_results.json`;a.click()};render();

const exampleCodes={collect_web_data:`async def collect_web_data(query, source_type, target_fields):\n    return await web.search(query, source_type, target_fields)`,analyze_item:`def analyze_item(item_input, research_data):\n    return llm.json("item_spec", item_input, research_data)`,analyze_market:`def analyze_market(item, market_data, analysis_type):\n    evidence = rag.search(market_data, item)\n    return llm.json("market_analysis", evidence)`,analyze_competitors:`def analyze_competitors(item, market_data, competitor_data):\n    return web.compare(item, market_data, competitor_data)`,analyze_team_capability:`def analyze_team_capability(team_data, item_requirements):\n    return llm.json("team_capability", team_data, item_requirements)`,define_development_goal:`def define_development_goal(item_spec, duration, target_field):\n    return llm.json("development_goal", item_spec, duration, target_field)`,define_development_method:`def define_development_method(core_technologies, constraints):\n    return llm.json("development_method", core_technologies, constraints)`,create_development_plan:`def create_development_plan(goals, duration, phases):\n    return plan.by_phase(goals, duration, phases)`,create_production_plan:`def create_production_plan(product, development_plan, phases):\n    return llm.json("production_plan", product, development_plan, phases)`,create_marketing_strategy:`def create_marketing_strategy(item, market, target_customer, stage):\n    return llm.json("marketing_strategy", item, market, target_customer, stage)`,create_business_model:`def create_business_model(item, market, customer, strategy):\n    return llm.json("business_model", item, market, customer, strategy)`,create_growth_strategy:`def create_growth_strategy(market, competitors, bm, investment, social_value):\n    return llm.json("growth_strategy", market, competitors, bm, investment, social_value)`,create_resource_plan:`def create_resource_plan(item, required_capabilities, team, resource_type):\n    return plan.resources(item, required_capabilities, team, resource_type)`,calculate_budget:`def calculate_budget(items, quantity, unit_price, phase, rules):\n    return python.check_budget(items, quantity, unit_price, phase, rules)`,create_schedule:`def create_schedule(tasks, duration, milestones):\n    return python.timeline(tasks, duration, milestones)`,generate_section:`def generate_section(section_spec, source_data, writing_rules):\n    return llm.text(section_spec, source_data, writing_rules)`,generate_table:`def generate_table(columns, rows, rules):\n    # 설계 전용: 현재 실행하지 않음\n    return {"columns": columns, "rows": rows, "rules": rules}`,generate_image_spec:`def generate_image_spec(item, architecture, flow_type):\n    return llm.json("image_spec", item, architecture, flow_type)`,validate_section:`def validate_section(section_spec, content, source_data):\n    return rubric.check(section_spec, content, source_data)`,assemble_document:`def assemble_document(sections, tables, images):\n    return hwp.compose(sections, tables, images)`};
