window.addEventListener('DOMContentLoaded',()=>{
  const button=document.getElementById('show-impact');
  const select=document.getElementById('retry-section');
  const output=document.getElementById('impact-list');
  if(!button||!select||!output)return;
  button.style.cursor='pointer';
  button.onclick=null;
  button.addEventListener('click',async()=>{
    if(!select.value){output.textContent='선택 가능한 사업계획서 항목이 없습니다.';return;}
    try{
      const type=(typeof current!=='undefined'?current:'general');
      const apiBase=(typeof api!=='undefined'?api:'http://127.0.0.1:8765');
      const response=await fetch(apiBase+'/api/impact?documentType='+encodeURIComponent(type)+'&sectionId='+encodeURIComponent(select.value));
      const plan=await response.json();
      const affected=(plan.affected||[]).filter(row=>row.sectionId!==select.value);
      output.innerHTML=affected.length
        ? '<b>연관 사업계획서 항목:</b> '+affected.map(row=>row.sectionId).join(', ')
        : '연관 사업계획서 항목 없음';
    }catch(error){output.textContent='연관 항목을 조회하지 못했습니다: '+error.message;}
  });
});




