// Keep hidden columns consistent after every result/retry/tab re-render.
window.addEventListener('DOMContentLoaded',()=>{
  const hiddenDefaults=['function명','모델','입력 매개변수·원본 경로','재작성 시 연쇄 실행 함수'];
  window.hiddenTableColumns=window.hiddenTableColumns||new Set();
  hiddenDefaults.forEach(name=>window.hiddenTableColumns.add(name));
  const applyHiddenColumns=()=>{
    const table=document.querySelector('#rows .table');
    if(!table)return;
    const headers=[...table.querySelectorAll('thead th')];
    table.querySelectorAll('tr').forEach(row=>[...row.children].forEach((cell,index)=>{
      const name=headers[index]?.textContent.trim();
      if(name)cell.style.display=window.hiddenTableColumns.has(name)?'none':'';
    }));
    document.querySelectorAll('#column-toggles input').forEach(box=>{
      const name=headers[Number(box.dataset.column)]?.textContent.trim();
      if(name)box.checked=!window.hiddenTableColumns.has(name);
    });
  };
  const host=document.getElementById('column-toggles');
  host?.addEventListener('change',event=>{
    const box=event.target.closest('input[data-column]');
    if(!box)return;
    const table=document.querySelector('#rows .table');
    const name=table?.querySelectorAll('thead th')[Number(box.dataset.column)]?.textContent.trim();
    if(name){if(box.checked)window.hiddenTableColumns.delete(name);else window.hiddenTableColumns.add(name);}
    applyHiddenColumns();
  });
  new MutationObserver(applyHiddenColumns).observe(document.getElementById('rows'),{childList:true,subtree:true});
  window.applyHiddenTableColumns=applyHiddenColumns;
  setTimeout(applyHiddenColumns,100);
});

// The result note can be inserted after DOMContentLoaded by an API response.
// Re-apply the status class when that asynchronous insertion happens.
(()=>{
  const applyValidationColors=()=>document.querySelectorAll('#rows .hint').forEach(note=>{
    const text=note.textContent||'';
    if(!text.includes('검증 1:'))return;
    const fail=text.includes('검증 1: fail')||text.includes('검증 1: validation1_failed');
    const pass=text.includes('검증 1: pass')||text.includes('검증 1: validation1_passed');
    note.classList.remove('validation-fail','validation-pass','validation-warning');
    note.classList.add(fail?'validation-fail':pass?'validation-pass':'validation-warning');
    if(fail){note.style.background='#fef3f2';note.style.color='#b42318';note.style.border='1px solid #fecdca'}
    else if(pass){note.style.background='#ecfdf3';note.style.color='#067647';note.style.border='1px solid #abefc6'}
    else {note.style.background='#fffaeb';note.style.color='#b54708';note.style.border='1px solid #fedf89'}
  });
  applyValidationColors();
  setInterval(applyValidationColors,500);
})();

